import{_ as r,u as l,o as d,c,a as t,b as i,d as o,w as n,r as f,e as s}from"./index-CRGB8mxT.js";const v="/assets/chiara_al_pianoforte_bn-BpZWvTlw.JPG",p="/assets/mani_pianoforte_2_bn-CQVveP87.JPG",m={class:"chi-sono"},u={class:"section section--alt didattica"},g={class:"container"},_={style:{"text-align":"center","margin-top":"2.5rem"}},h={class:"section section--dark cta-section"},b={class:"container",style:{"text-align":"center"}},z={__name:"ChiSonoPage",setup(C){return l({title:"Chi Sono | Chiara Dalla Torre - Pianoforte",meta:[{name:"description",content:"Scopri il percorso di Chiara Dalla Torre: dagli studi al Conservatorio Steffani alle Masterclass internazionali, dalle arti marziali alla didattica pianistica."},{name:"keywords",content:"Chiara Dalla Torre biografia, pianista San Donà di Piave, Conservatorio Steffani, arti marziali e musica, compositrici donne, Clara Schumann, Fanny Mendelssohn, insegnante pianoforte"}]}),(y,a)=>{const e=f("router-link");return d(),c("div",m,[a[6]||(a[6]=t('<section class="page-hero" data-v-f3f46e29><div class="container" data-v-f3f46e29><h1 data-v-f3f46e29>Chi Sono</h1><div class="section__divider" style="margin-top:1rem;" data-v-f3f46e29></div><p class="page-hero__sub" data-v-f3f46e29> Dalla musica alla disciplina, il mio percorso verso l&#39;insegnamento </p></div></section><section class="section bio" data-v-f3f46e29><div class="container" data-v-f3f46e29><div class="bio__grid" data-v-f3f46e29><div class="bio__content" data-v-f3f46e29><h2 data-v-f3f46e29>Il Mio Percorso Musicale</h2><div class="section__divider" style="margin-left:0;" data-v-f3f46e29></div><p data-v-f3f46e29> Nata a <strong data-v-f3f46e29>San Donà di Piave nel 1993</strong>, ho iniziato lo studio del pianoforte all&#39;età di 9 anni. A 13 anni sono stata ammessa al <strong data-v-f3f46e29>Conservatorio di Musica &quot;A. Steffani&quot;</strong> di Castelfranco Veneto, dove ho studiato sotto la guida del M° Francesco Bencivenga. Nel 2010 ho proseguito i miei studi seguita dal M° Irene Russo, <strong data-v-f3f46e29>diplomandomi brillantemente nel 2016</strong>. </p><p data-v-f3f46e29> Durante gli anni di Conservatorio ho avuto l&#39;opportunità di seguire <strong data-v-f3f46e29>Masterclass con pianisti di fama internazionale</strong>: Pietro de Maria, Filippo Gamba, Andrea Lucchesini, Jesús M. Gómez Rodríguez, Brenno Ambrosini, Sébastien Risler e Annibale Rebaudengo. Ognuno di questi incontri ha arricchito il mio linguaggio musicale e la mia sensibilità interpretativa. </p><h3 style="margin-top:2rem;" data-v-f3f46e29>Attività Concertistica</h3><p data-v-f3f46e29> Tra il 2011 e il 2016 ho partecipato annualmente alla rassegna <em data-v-f3f46e29>Sabati in Villa</em> presso Villa Barbarella di Castelfranco Veneto, sia come solista che in formazioni cameristiche. </p><p data-v-f3f46e29> Nel 2012 ho preso parte al progetto <em data-v-f3f46e29>L&#39;integrale dei concerti per 2, 3 e 4 tastiere e orchestra di J.S. Bach</em>, eseguendo il Concerto per due tastiere e orchestra in Do minore BWV 1062 presso il Teatro Accademico di Castelfranco Veneto. </p><p data-v-f3f46e29> Per molti anni ho affiancato all&#39;attività solistica anche quella di <strong data-v-f3f46e29>duo pianistico</strong> con la pianista italo-giapponese Anna Sembokuya Samarani, esibendomi alla rassegna pianistica itinerante <em data-v-f3f46e29>InterPiano Duo</em>, organizzata in collaborazione con i conservatori &quot;Arrigo Pedrollo&quot; di Vicenza e &quot;Benedetto Marcello&quot; di Venezia. </p><p data-v-f3f46e29> Ho dedicato gran parte del mio percorso di studi alla <strong data-v-f3f46e29>musica da camera</strong>, affrontando repertori vasti con formazioni differenti, intensificando la preparazione principalmente nella formazione di duo e trio con flauto traverso. </p></div><div class="bio__sidebar" data-v-f3f46e29><img src="'+v+'" alt="Chiara Dalla Torre al pianoforte" class="bio__image-photo" loading="lazy" data-v-f3f46e29><div class="bio__highlights" data-v-f3f46e29><div class="bio__highlight" data-v-f3f46e29><span class="bio__highlight-number" data-v-f3f46e29>2016</span><span class="bio__highlight-label" data-v-f3f46e29>Diploma al Conservatorio</span></div><div class="bio__highlight" data-v-f3f46e29><span class="bio__highlight-number" data-v-f3f46e29>15+</span><span class="bio__highlight-label" data-v-f3f46e29>Anni di studio</span></div><div class="bio__highlight" data-v-f3f46e29><span class="bio__highlight-number" data-v-f3f46e29>2</span><span class="bio__highlight-label" data-v-f3f46e29>Produzioni discografiche</span></div></div></div></div></div></section><section class="section section--alt international" data-v-f3f46e29><div class="container" data-v-f3f46e29><h2 class="section__title" data-v-f3f46e29>Esperienze Internazionali</h2><div class="section__divider" data-v-f3f46e29></div><p class="section__subtitle" data-v-f3f46e29> Le mie esperienze oltre l&#39;Italia </p><div class="timeline" data-v-f3f46e29><div class="timeline__item" data-v-f3f46e29><div class="timeline__year" data-v-f3f46e29>2011</div><div class="timeline__content" data-v-f3f46e29><h3 data-v-f3f46e29>Royal Conservatory — Anversa, Belgio</h3><p data-v-f3f46e29>Selezionata per uno stage pianistico presso il prestigioso conservatorio belga.</p></div></div><div class="timeline__item" data-v-f3f46e29><div class="timeline__year" data-v-f3f46e29>2015</div><div class="timeline__content" data-v-f3f46e29><h3 data-v-f3f46e29>Lemmensinstituut — Lovanio, Belgio</h3><p data-v-f3f46e29>Esibizione presso l&#39;istituto musicale di Lovanio.</p></div></div><div class="timeline__item" data-v-f3f46e29><div class="timeline__year" data-v-f3f46e29>2016</div><div class="timeline__content" data-v-f3f46e29><h3 data-v-f3f46e29>Prima Produzione Discografica</h3><p data-v-f3f46e29> Registrazione di musiche di Bach/Busoni, pubblicata dal Conservatorio di Castelfranco Veneto. </p></div></div><div class="timeline__item" data-v-f3f46e29><div class="timeline__year" data-v-f3f46e29>2018</div><div class="timeline__content" data-v-f3f46e29><h3 data-v-f3f46e29>Auditorium Maene — Bruxelles, Belgio</h3><p data-v-f3f46e29>Concerto presso il rinomato Auditorium Maene nella capitale belga.</p></div></div><div class="timeline__item" data-v-f3f46e29><div class="timeline__year" data-v-f3f46e29>2024</div><div class="timeline__content" data-v-f3f46e29><h3 data-v-f3f46e29>Produzione Discografica</h3><p data-v-f3f46e29>Registrazione del progetto dedicato alle donne compositrici.</p></div></div></div></div></section><section id="arti-marziali" class="section martial" data-v-f3f46e29><div class="container" data-v-f3f46e29><div class="martial__grid" data-v-f3f46e29><div class="martial__content" data-v-f3f46e29><h2 data-v-f3f46e29>Arti Marziali e Musica</h2><div class="section__divider" style="margin-left:0;" data-v-f3f46e29></div><p class="martial__intro" data-v-f3f46e29> Un binomio inaspettato che ha trasformato profondamente il mio modo di vivere la musica e l&#39;insegnamento. </p><p data-v-f3f46e29> La pratica delle arti marziali è entrata nella mia vita come una disciplina parallela al pianoforte, e nel tempo si è rivelata una fonte straordinaria di crescita personale e artistica. Ciò che inizialmente poteva sembrare un mondo lontano dalla musica si è rivelato sorprendentemente complementare. </p><p data-v-f3f46e29> Praticare arti marziali mi ha permesso di avere una maggiore <strong data-v-f3f46e29>consapevolezza del corpo</strong> e, al pianoforte, di controllare e poi trasmettere una gestualità consapevole. </p><p data-v-f3f46e29> La <strong data-v-f3f46e29>concentrazione</strong> e la <strong data-v-f3f46e29>presenza</strong> permettono di essere completamente immersi in ciò che stiamo facendo, sia esso un momento di studio, una lezione o un&#39;esecuzione pubblica. </p><p data-v-f3f46e29> E per finire, prima il pianoforte e poi le arti marziali mi hanno insegnato la <strong data-v-f3f46e29>perseveranza nel percorso</strong>: il progresso arriva attraverso la ripetizione paziente e la fiducia nel processo. Non esistono scorciatoie, ogni passo è un mattone fondamentale. </p></div><div class="martial__visual" data-v-f3f46e29><div class="martial__quote-card" data-v-f3f46e29><blockquote data-v-f3f46e29> &quot;La disciplina è il ponte tra obiettivi e risultati.&quot; </blockquote><cite data-v-f3f46e29>— Jim Rohn</cite></div><img src="'+p+'" alt="Mani al pianoforte - disciplina e arte" class="martial__image-photo" loading="lazy" data-v-f3f46e29></div></div></div></section>',4)),i("section",u,[i("div",g,[a[1]||(a[1]=t('<h2 class="section__title" data-v-f3f46e29>Formazione Didattica</h2><div class="section__divider" data-v-f3f46e29></div><p class="section__subtitle" data-v-f3f46e29> Un percorso continuo di crescita professionale nell&#39;arte dell&#39;insegnamento </p><div class="didattica__content" data-v-f3f46e29><p data-v-f3f46e29> La mia attività didattica è frutto di un percorso mirato svolto negli anni di studio, attraverso <strong data-v-f3f46e29>tirocinio attivo di classe</strong> presso il Conservatorio e l&#39;esperienza in varie scuole private. </p><p data-v-f3f46e29> Nel 2021 ho preso parte al <strong data-v-f3f46e29>Corso di formazione metodologica e didattica strumentale pianistica</strong>, un&#39;esperienza fondamentale incentrata sul repertorio, la prassi e l&#39;approccio risolutivo, con particolare focus sulle varie metodologie di insegnamento e i metodi utilizzati. </p></div><div id="voci-dal-silenzio" class="didattica__content voci" data-v-f3f46e29><h3 data-v-f3f46e29>Voci dal Silenzio: Le Compositrici Dimenticate</h3><div class="section__divider" data-v-f3f46e29></div><p class="voci__intro" data-v-f3f46e29> Per secoli, donne straordinarie hanno composto musica di altissimo valore, spesso ai margini della storia. Riscoprirle è un atto di giustizia e di arricchimento musicale. </p><p data-v-f3f46e29> Durante il mio percorso di formazione, ho avuto l&#39;opportunità di approfondire il tema della <strong data-v-f3f46e29>donna-musicista</strong> attraverso un corso dedicato, dove sono state prese in esame le vite e le opere di compositrici che hanno vissuto ai margini in un periodo storico di enorme produzione musicale. </p><p data-v-f3f46e29> Questa esperienza ha trasformato profondamente la mia visione del repertorio: non si tratta solo di riscoprire brani dimenticati, ma di restituire una voce a personalità artistiche che meritano il loro posto nella storia della musica. Oggi integro attivamente compositrici come <strong data-v-f3f46e29>Clara Schumann</strong>, <strong data-v-f3f46e29>Amy Beach</strong>, <strong data-v-f3f46e29>Fanny Mendelssohn</strong> e <strong data-v-f3f46e29>Cécile Chaminade</strong> nelle mie lezioni e nei miei programmi. </p><p data-v-f3f46e29> Integrare questo repertorio nello studio del pianoforte non è solo un atto di riscoperta: è un modo per offrire agli allievi una visione più completa e onesta della storia della musica. </p></div>',5)),i("div",_,[o(e,{to:"/lezioni",class:"btn btn--primary"},{default:n(()=>[...a[0]||(a[0]=[s(" Scopri le mie Lezioni ",-1)])]),_:1})])])]),i("section",h,[i("div",b,[a[3]||(a[3]=i("h2",null,"Vuoi Conoscermi Meglio?",-1)),a[4]||(a[4]=i("div",{class:"section__divider",style:{background:"var(--color-accent)"}},null,-1)),a[5]||(a[5]=i("p",{style:{"max-width":"500px",margin:"0 auto",color:"rgba(240,236,228,0.85)","font-size":"1.05rem"}}," Scrivimi per scoprire come possiamo iniziare insieme un percorso musicale su misura per te. ",-1)),o(e,{to:"/contatti",class:"btn btn--light",style:{"margin-top":"1.5rem"}},{default:n(()=>[...a[2]||(a[2]=[s(" Contattami ",-1)])]),_:1})])])])}}},P=r(z,[["__scopeId","data-v-f3f46e29"]]);export{P as default};
